import React, { useEffect, useRef } from 'react';
import styled, { keyframes } from 'styled-components';

const skills = [
  { icon: '🧩', label: 'Organizational Design' },
  { icon: '👥', label: 'Talent Management' },
  { icon: '🗂️', label: 'Project Planning' },
  { icon: '💻', label: 'Digital Transformation' },
  { icon: '🌱', label: 'Sustainability' },
  { icon: '💡', label: 'Product Development' },
  { icon: '📊', label: 'Management' },
  { icon: '🧭', label: 'Strategy' },
  { icon: '⚙️', label: 'Project Optimization' },
];

const fadeInUp = keyframes`
  from {
    opacity: 0;
    transform: translateY(30px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
`;

const SkillsSection = styled.section`
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 3.5rem 2rem 2.5rem 2rem;
  display: flex;
  flex-direction: column;
  align-items: center;
`;

const SkillsGrid = styled.div`
  display: flex;
  flex-wrap: wrap;
  gap: 1.2rem 1.1rem;
  justify-content: center;
  margin-top: 0.5rem;
`;

const SkillPill = styled.div`
  display: flex;
  align-items: center;
  gap: 0.7rem;
  background: ${({ theme }) => theme.bg === '#fff' ? '#f4f4f4' : '#181818'};
  color: ${({ theme }) => theme.text};
  border-radius: 2rem;
  padding: 0.7rem 1.4rem 0.7rem 1.1rem;
  font-size: 1.08rem;
  font-weight: 500;
  box-shadow: 0 1px 8px 0 rgba(0,0,0,0.06);
  opacity: 0;
  animation: ${fadeInUp} 0.7s forwards;
  animation-delay: ${({ delay }) => delay}s;
`;

const Skills = () => {
  return (
    <SkillsSection id="skills">
      <SkillsGrid>
        {skills.map((skill, i) => (
          <SkillPill key={skill.label} delay={0.1 + i * 0.08}>
            <span style={{ fontSize: '1.25em' }}>{skill.icon}</span>
            {skill.label}
          </SkillPill>
        ))}
      </SkillsGrid>
    </SkillsSection>
  );
};

export default Skills;
